window.GB_NCERT_QUESTIONS.push(...[{"id":"ncert7-social-science-1","grade":7,"subject":"Social Science","chapterNo":1,"chapter":"Geographical Diversity of India","level":"easy","q":"Which landform is a high area of flat or gently rolling land?","options":["Plateau","Valley","Delta","Coastal lagoon"],"correct":0,"why":"A plateau is an elevated area with a relatively level surface."},{"id":"ncert7-social-science-2","grade":7,"subject":"Social Science","chapterNo":1,"chapter":"Geographical Diversity of India","level":"medium","q":"Why do the Himalayas influence India's geography?","options":["They form a major mountain barrier and affect rivers and climate","They are a coral island chain","They form India's southern coastline","They are a desert plain"],"correct":0,"why":"The Himalayas shape drainage, climate and settlement patterns in northern India."},{"id":"ncert7-social-science-3","grade":7,"subject":"Social Science","chapterNo":2,"chapter":"Understanding the Weather","level":"easy","q":"Which instrument measures atmospheric pressure?","options":["Barometer","Rain gauge","Thermometer","Anemometer"],"correct":0,"why":"A barometer measures atmospheric pressure."},{"id":"ncert7-social-science-4","grade":7,"subject":"Social Science","chapterNo":2,"chapter":"Understanding the Weather","level":"medium","q":"What does a rain gauge measure?","options":["Amount of rainfall","Wind direction","Air pressure","Sunlight duration"],"correct":0,"why":"A rain gauge collects and measures precipitation over a period."},{"id":"ncert7-social-science-5","grade":7,"subject":"Social Science","chapterNo":3,"chapter":"Climates of India","level":"easy","q":"Climate refers to:","options":["Long-term pattern of weather in a region","Weather at one moment","A single thunderstorm","Only daily temperature"],"correct":0,"why":"Climate describes average weather patterns over long periods."},{"id":"ncert7-social-science-6","grade":7,"subject":"Social Science","chapterNo":3,"chapter":"Climates of India","level":"medium","q":"Which factor strongly affects the climate of a place?","options":["Latitude and altitude","The colour of buildings","The number of road signs","The local currency"],"correct":0,"why":"Latitude and altitude are among the important controls of climate."},{"id":"ncert7-social-science-7","grade":7,"subject":"Social Science","chapterNo":4,"chapter":"New Beginnings: Cities and States","level":"easy","q":"What is meant by the Second Urbanisation in ancient India?","options":["The growth of cities again during the first millennium BCE","The first village settlement","The decline of all trade","The building of modern metros"],"correct":0,"why":"The term refers to renewed urban growth in the Ganga plains and nearby regions during the first millennium BCE."},{"id":"ncert7-social-science-8","grade":7,"subject":"Social Science","chapterNo":4,"chapter":"New Beginnings: Cities and States","level":"medium","q":"A janapada was broadly:","options":["A territory associated with a people or clan","A modern district office","A sea port only","A type of coin"],"correct":0,"why":"Janapada refers to a territory where a people had settled."},{"id":"ncert7-social-science-9","grade":7,"subject":"Social Science","chapterNo":5,"chapter":"The Rise of Empires","level":"easy","q":"Which ruler is associated with the Mauryan Empire and the Kalinga war?","options":["Ashoka","Harsha","Samudragupta","Pulakeshin II"],"correct":0,"why":"Ashoka's campaign in Kalinga is a major event in Mauryan history."},{"id":"ncert7-social-science-10","grade":7,"subject":"Social Science","chapterNo":5,"chapter":"The Rise of Empires","level":"medium","q":"Why are inscriptions useful to historians?","options":["They provide evidence about rulers, events and grants","They always tell every detail without bias","They are only decorative","They replace archaeological evidence"],"correct":0,"why":"Inscriptions are primary historical sources, though they must be interpreted critically."},{"id":"ncert7-social-science-11","grade":7,"subject":"Social Science","chapterNo":6,"chapter":"The Age of Reorganisation","level":"easy","q":"What does the term 'reorganisation' suggest in a historical period?","options":["Changes in political powers and regional arrangements","No change in society","Only a change in weather","A change in the alphabet"],"correct":0,"why":"The chapter examines political changes and the reorganisation of powers and kingdoms."},{"id":"ncert7-social-science-12","grade":7,"subject":"Social Science","chapterNo":6,"chapter":"The Age of Reorganisation","level":"medium","q":"Which evidence can help study changing kingdoms?","options":["Coins, inscriptions and literary sources","Only modern advertisements","Only weather forecasts","Only fictional stories"],"correct":0,"why":"Historians compare multiple kinds of evidence to reconstruct the past."},{"id":"ncert7-social-science-13","grade":7,"subject":"Social Science","chapterNo":7,"chapter":"The Gupta Era: An Age of Tireless Creativity","level":"easy","q":"The Gupta period is often noted for developments in:","options":["Literature, science, art and learning","Steam locomotives","Internet technology","Modern parliamentary elections"],"correct":0,"why":"The Gupta era is associated with notable cultural, scientific and intellectual achievements."},{"id":"ncert7-social-science-14","grade":7,"subject":"Social Science","chapterNo":7,"chapter":"The Gupta Era: An Age of Tireless Creativity","level":"medium","q":"Why should historians avoid calling any age a 'golden age' for everyone without qualification?","options":["Benefits and experiences differed across social groups","Every person always had identical experiences","No sources exist from the past","All regions were politically identical"],"correct":0,"why":"Historical labels need nuance because prosperity and power were not shared equally."},{"id":"ncert7-social-science-15","grade":7,"subject":"Social Science","chapterNo":8,"chapter":"How the Land Becomes Sacred","level":"easy","q":"A sacred landscape can include:","options":["Rivers, mountains, forests and pilgrimage places","Only shopping malls","Only factories","Only highways"],"correct":0,"why":"Cultural traditions often attach sacred meaning to natural features and places."},{"id":"ncert7-social-science-16","grade":7,"subject":"Social Science","chapterNo":8,"chapter":"How the Land Becomes Sacred","level":"medium","q":"Why do pilgrimage routes matter culturally?","options":["They connect communities, stories and places","They prevent all cultural exchange","They exist only for trade taxes","They erase regional identities"],"correct":0,"why":"Pilgrimage networks help connect people and transmit shared traditions."},{"id":"ncert7-social-science-17","grade":7,"subject":"Social Science","chapterNo":9,"chapter":"From the Rulers to the Ruled: Types of Governments","level":"easy","q":"In a democracy, political power ultimately rests with:","options":["The people","A hereditary ruler alone","The military alone","A private company"],"correct":0,"why":"Democracy is based on the people choosing and holding representatives accountable."},{"id":"ncert7-social-science-18","grade":7,"subject":"Social Science","chapterNo":9,"chapter":"From the Rulers to the Ruled: Types of Governments","level":"medium","q":"A monarchy differs from a republic mainly because:","options":["A monarch is usually the head of state by hereditary succession","All citizens elect a king for life","A republic has no laws","A monarchy has no territory"],"correct":0,"why":"Monarchies commonly have hereditary heads of state; republics do not."},{"id":"ncert7-social-science-19","grade":7,"subject":"Social Science","chapterNo":10,"chapter":"The Constitution of India — An Introduction","level":"easy","q":"The Preamble to the Indian Constitution begins with which words?","options":["We, the People of India","The Parliament commands","The President declares","The States decide alone"],"correct":0,"why":"The Preamble begins with 'We, the People of India'."},{"id":"ncert7-social-science-20","grade":7,"subject":"Social Science","chapterNo":10,"chapter":"The Constitution of India — An Introduction","level":"medium","q":"Why is a constitution important?","options":["It establishes principles, institutions and limits of government","It replaces every ordinary law automatically","It gives unlimited power to one office","It is only a list of festivals"],"correct":0,"why":"A constitution defines the framework of government and citizens' rights and duties."},{"id":"ncert7-social-science-21","grade":7,"subject":"Social Science","chapterNo":11,"chapter":"From Barter to Money","level":"easy","q":"Barter is a system in which people:","options":["Exchange goods or services directly","Use only digital wallets","Borrow from a central bank","Pay income tax"],"correct":0,"why":"Barter involves direct exchange without using money as an intermediary."},{"id":"ncert7-social-science-22","grade":7,"subject":"Social Science","chapterNo":11,"chapter":"From Barter to Money","level":"medium","q":"One limitation of barter is:","options":["Both parties must want what the other offers","It always requires internet access","It cannot exchange food","It uses too many banknotes"],"correct":0,"why":"Barter can be difficult when each party does not need the other's goods at the same time."},{"id":"ncert7-social-science-23","grade":7,"subject":"Social Science","chapterNo":12,"chapter":"Understanding Markets","level":"easy","q":"What is a market?","options":["A system or place where buyers and sellers exchange goods or services","Only a weekly village fair","Only a stock exchange building","A government school"],"correct":0,"why":"Markets can be physical or online systems connecting buyers and sellers."},{"id":"ncert7-social-science-24","grade":7,"subject":"Social Science","chapterNo":12,"chapter":"Understanding Markets","level":"medium","q":"Why might the same product have different prices in different shops?","options":["Costs, location, quality and competition can differ","All shops use the same supplier always","Prices are decided by weather alone","Products have no costs"],"correct":0,"why":"Several factors, including costs and competition, can influence prices."},{"id":"ncert7-social-science-25","grade":7,"subject":"Social Science","chapterNo":13,"chapter":"The Story of Indian Farming","level":"easy","q":"Which is a kharif crop commonly grown during the monsoon season?","options":["Rice","Wheat","Mustard","Gram"],"correct":0,"why":"Rice is commonly grown as a kharif crop in many parts of India."},{"id":"ncert7-social-science-26","grade":7,"subject":"Social Science","chapterNo":13,"chapter":"The Story of Indian Farming","level":"medium","q":"Why is irrigation important for farming?","options":["It supplies water when rainfall is insufficient or irregular","It removes the need for soil","It guarantees no pests","It replaces seeds"],"correct":0,"why":"Irrigation supports crops when rain is inadequate or unevenly distributed."},{"id":"ncert7-social-science-27","grade":7,"subject":"Social Science","chapterNo":14,"chapter":"India and Her Neighbours","level":"easy","q":"Which is one of India's land neighbours?","options":["Nepal","Sri Lanka","Maldives","Mauritius"],"correct":0,"why":"Nepal shares a land boundary with India."},{"id":"ncert7-social-science-28","grade":7,"subject":"Social Science","chapterNo":14,"chapter":"India and Her Neighbours","level":"medium","q":"Which pair are island neighbours of India in the Indian Ocean?","options":["Sri Lanka and Maldives","Nepal and Bhutan","China and Afghanistan","Pakistan and Bangladesh"],"correct":0,"why":"Sri Lanka and the Maldives are island countries in India's maritime neighbourhood."},{"id":"ncert7-social-science-29","grade":7,"subject":"Social Science","chapterNo":15,"chapter":"Empires and Kingdoms: 6th to 10th Centuries","level":"easy","q":"The tripartite struggle for Kannauj involved which three powers?","options":["Palas, Gurjara-Pratiharas and Rashtrakutas","Mauryas, Guptas and Cholas","Mughals, Marathas and Sikhs","Cholas, Cheras and Pandyas only"],"correct":0,"why":"The Pala, Gurjara-Pratihara and Rashtrakuta powers competed for control of Kannauj."},{"id":"ncert7-social-science-30","grade":7,"subject":"Social Science","chapterNo":15,"chapter":"Empires and Kingdoms: 6th to 10th Centuries","level":"medium","q":"Which source can reveal information about early medieval land grants?","options":["Copper-plate inscriptions","Modern bank statements","Weather charts","Cinema posters"],"correct":0,"why":"Copper-plate grants record land donations and administrative details."},{"id":"ncert7-social-science-31","grade":7,"subject":"Social Science","chapterNo":16,"chapter":"Turning Tides: 11th and 12th Centuries","level":"easy","q":"The Cholas are especially known for their:","options":["Powerful maritime activity and temple architecture","Arctic exploration","Printing press industry","Modern railway network"],"correct":0,"why":"The Cholas developed strong naval and maritime connections and notable temple architecture."},{"id":"ncert7-social-science-32","grade":7,"subject":"Social Science","chapterNo":16,"chapter":"Turning Tides: 11th and 12th Centuries","level":"medium","q":"Angkor Wat is located in present-day:","options":["Cambodia","India","Nepal","Sri Lanka"],"correct":0,"why":"Angkor Wat is a major temple complex in Cambodia."},{"id":"ncert7-social-science-33","grade":7,"subject":"Social Science","chapterNo":17,"chapter":"India, a Home to Many","level":"easy","q":"The phrase 'India, a Home to Many' highlights:","options":["Migration, settlement and cultural pluralism","A single unchanging community","The absence of trade","Only one language"],"correct":0,"why":"The chapter focuses on communities that came to India and made it home."},{"id":"ncert7-social-science-34","grade":7,"subject":"Social Science","chapterNo":17,"chapter":"India, a Home to Many","level":"medium","q":"Cultural pluralism means:","options":["Different communities and traditions coexist in society","Everyone must share one custom","No cultural exchange is possible","Only one religion can exist"],"correct":0,"why":"Pluralism recognises and accommodates different communities and traditions."},{"id":"ncert7-social-science-35","grade":7,"subject":"Social Science","chapterNo":18,"chapter":"The State, the Government, and You","level":"easy","q":"In India, the legislature's main function is to:","options":["Make laws","Conduct court trials","Command every private business","Issue weather alerts"],"correct":0,"why":"The legislature is the law-making branch of government."},{"id":"ncert7-social-science-36","grade":7,"subject":"Social Science","chapterNo":18,"chapter":"The State, the Government, and You","level":"medium","q":"What is the role of the permanent executive or civil service?","options":["Implement policies and provide administrative continuity","Replace elected representatives","Decide court verdicts","Run political parties"],"correct":0,"why":"Civil servants support administration and implement lawful government decisions."},{"id":"ncert7-social-science-37","grade":7,"subject":"Social Science","chapterNo":19,"chapter":"Infrastructure: Engine of India’s Development","level":"easy","q":"Which is an example of infrastructure?","options":["Roads, railways and communication networks","A family recipe","A personal hobby","A school examination answer"],"correct":0,"why":"Infrastructure includes essential physical and organisational systems that support society and the economy."},{"id":"ncert7-social-science-38","grade":7,"subject":"Social Science","chapterNo":19,"chapter":"Infrastructure: Engine of India’s Development","level":"medium","q":"Why are ports important to a country's economy?","options":["They support maritime trade and movement of goods","They produce rainfall","They replace all roads","They are used only for fishing"],"correct":0,"why":"Ports connect sea transport with domestic and international trade."},{"id":"ncert7-social-science-39","grade":7,"subject":"Social Science","chapterNo":20,"chapter":"Banks and the Magic of Finance","level":"easy","q":"What is the main role of a bank?","options":["Accept deposits and provide loans and payment services","Print all currency without authority","Set every shop's prices","Make laws for Parliament"],"correct":0,"why":"Banks provide deposit, lending and payment services."},{"id":"ncert7-social-science-40","grade":7,"subject":"Social Science","chapterNo":20,"chapter":"Banks and the Magic of Finance","level":"medium","q":"Which is a safer digital payment practice?","options":["Verify the recipient and never share your UPI PIN","Share your PIN with callers","Approve unknown collect requests","Click every payment link"],"correct":0,"why":"Verifying the recipient and keeping the PIN secret helps prevent fraud."}]);

/* Class 7 Curiosity Science: original practice questions across the 12 current chapters. */
window.GB_NCERT_QUESTIONS.push(...[{"id":"ncert7-science-1-1","grade":7,"subject":"Science","chapterNo":1,"chapter":"The Ever-Evolving World of Science","level":"easy","q":"Why do scientists repeat an experiment several times?","options":["To check whether results are consistent","To change the result deliberately","To avoid recording observations","To make the experiment longer without purpose"],"correct":0,"why":"Repeated trials help check reliability and reveal unusual results."},{"id":"ncert7-science-1-2","grade":7,"subject":"Science","chapterNo":1,"chapter":"The Ever-Evolving World of Science","level":"medium","q":"Which is the best way to investigate a question scientifically?","options":["Make observations, form a testable idea and collect evidence","Choose an answer before observing","Ignore results that disagree","Change many variables without recording them"],"correct":0,"why":"Scientific inquiry uses observations, testable questions and evidence."},{"id":"ncert7-science-2-1","grade":7,"subject":"Science","chapterNo":2,"chapter":"Exploring Substances: Acidic, Basic, and Neutral","level":"easy","q":"Which substance is acidic?","options":["Lemon juice","Soap solution","Baking soda solution","Distilled water"],"correct":0,"why":"Lemon juice contains citric acid and is acidic."},{"id":"ncert7-science-2-2","grade":7,"subject":"Science","chapterNo":2,"chapter":"Exploring Substances: Acidic, Basic, and Neutral","level":"medium","q":"What happens to blue litmus paper in an acidic solution?","options":["It turns red","It turns green","It remains blue in every acid","It becomes colourless"],"correct":0,"why":"Acids turn blue litmus red."},{"id":"ncert7-science-3-1","grade":7,"subject":"Science","chapterNo":3,"chapter":"Electricity: Circuits and their Components","level":"easy","q":"Which component provides electrical energy in a simple circuit?","options":["Cell or battery","Switch","Connecting wire","Bulb"],"correct":0,"why":"A cell supplies electrical energy to the circuit."},{"id":"ncert7-science-3-2","grade":7,"subject":"Science","chapterNo":3,"chapter":"Electricity: Circuits and their Components","level":"medium","q":"A bulb glows in a simple circuit when:","options":["The circuit is closed and complete","The switch is open","A wire is disconnected","There is no energy source"],"correct":0,"why":"Current flows through a complete closed circuit."},{"id":"ncert7-science-4-1","grade":7,"subject":"Science","chapterNo":4,"chapter":"The World of Metals and Non-metals","level":"easy","q":"Which property is generally typical of metals?","options":["They conduct heat and electricity well","They are always gases","They cannot be shaped","They are all transparent"],"correct":0,"why":"Most metals are good conductors of heat and electricity."},{"id":"ncert7-science-4-2","grade":7,"subject":"Science","chapterNo":4,"chapter":"The World of Metals and Non-metals","level":"medium","q":"Rusting of iron usually requires:","options":["Oxygen and moisture","Only sunlight","Only nitrogen","Only dry sand"],"correct":0,"why":"Iron rusts when exposed to oxygen and water or moisture."},{"id":"ncert7-science-5-1","grade":7,"subject":"Science","chapterNo":5,"chapter":"Changes Around Us: Physical and Chemical","level":"easy","q":"Which is a chemical change?","options":["Burning of paper","Folding a sheet of paper","Cutting cloth","Melting ice"],"correct":0,"why":"Burning forms new substances, so it is a chemical change."},{"id":"ncert7-science-5-2","grade":7,"subject":"Science","chapterNo":5,"chapter":"Changes Around Us: Physical and Chemical","level":"medium","q":"Which change is usually reversible?","options":["Melting ice and refreezing the water","Burning wood","Cooking an egg","Rusting an iron nail"],"correct":0,"why":"Water can freeze again after melting; no new substance is formed."},{"id":"ncert7-science-6-1","grade":7,"subject":"Science","chapterNo":6,"chapter":"Adolescence: A Stage of Growth and Change","level":"easy","q":"Adolescence is the stage when:","options":["The body undergoes changes towards adulthood","Growth stops permanently","Only height decreases","No emotional changes occur"],"correct":0,"why":"Adolescence involves physical, emotional and social changes."},{"id":"ncert7-science-6-2","grade":7,"subject":"Science","chapterNo":6,"chapter":"Adolescence: A Stage of Growth and Change","level":"medium","q":"Which habit supports health during adolescence?","options":["Balanced food, sleep and regular physical activity","Skipping meals regularly","Avoiding sleep","Taking medicines without advice"],"correct":0,"why":"Healthy routines support growth and wellbeing during adolescence."},{"id":"ncert7-science-7-1","grade":7,"subject":"Science","chapterNo":7,"chapter":"Heat Transfer in Nature","level":"easy","q":"Heat transfer through a solid mainly by particle-to-particle interaction is:","options":["Conduction","Convection","Radiation only","Evaporation"],"correct":0,"why":"Conduction transfers heat through interactions between neighbouring particles."},{"id":"ncert7-science-7-2","grade":7,"subject":"Science","chapterNo":7,"chapter":"Heat Transfer in Nature","level":"medium","q":"Why does warm air generally rise?","options":["It expands, becomes less dense and moves upward","It becomes heavier than cold air","It loses all energy","Gravity stops acting on it"],"correct":0,"why":"Heating makes air expand and become less dense than surrounding cooler air."},{"id":"ncert7-science-8-1","grade":7,"subject":"Science","chapterNo":8,"chapter":"Measurement of Time and Motion","level":"easy","q":"Speed is calculated as:","options":["Distance divided by time","Time divided by distance","Distance multiplied by time","Distance plus time"],"correct":0,"why":"Speed is the distance travelled per unit time."},{"id":"ncert7-science-8-2","grade":7,"subject":"Science","chapterNo":8,"chapter":"Measurement of Time and Motion","level":"medium","q":"A pendulum completes one oscillation when it:","options":["Moves from one extreme to the other and back","Moves only halfway","Stops at the centre","Makes one full circle"],"correct":0,"why":"One oscillation is a complete to-and-fro motion."},{"id":"ncert7-science-9-1","grade":7,"subject":"Science","chapterNo":9,"chapter":"Life Processes in Animals","level":"easy","q":"Which gas is present in greater amount in exhaled air than in inhaled air?","options":["Carbon dioxide","Oxygen","Helium","Hydrogen"],"correct":0,"why":"Cellular respiration produces carbon dioxide, which is exhaled."},{"id":"ncert7-science-9-2","grade":7,"subject":"Science","chapterNo":9,"chapter":"Life Processes in Animals","level":"medium","q":"Which organ is primarily responsible for pumping blood around the body?","options":["Heart","Lungs","Stomach","Kidney"],"correct":0,"why":"The heart pumps blood through the circulatory system."},{"id":"ncert7-science-10-1","grade":7,"subject":"Science","chapterNo":10,"chapter":"Life Processes in Plants","level":"easy","q":"Which plant structure mainly absorbs water and minerals from soil?","options":["Roots","Flowers","Fruits","Seeds"],"correct":0,"why":"Roots absorb water and mineral nutrients from the soil."},{"id":"ncert7-science-10-2","grade":7,"subject":"Science","chapterNo":10,"chapter":"Life Processes in Plants","level":"medium","q":"Photosynthesis uses which inputs?","options":["Light, water and carbon dioxide","Oxygen, sugar and darkness","Nitrogen and soil only","Only water"],"correct":0,"why":"Plants use light energy to convert water and carbon dioxide into sugars, releasing oxygen."},{"id":"ncert7-science-11-1","grade":7,"subject":"Science","chapterNo":11,"chapter":"Light: Shadows and Reflections","level":"easy","q":"A shadow forms when:","options":["An opaque object blocks light","Sound is blocked","Air becomes cold","A transparent sheet creates darkness by itself"],"correct":0,"why":"A shadow forms when an object blocks light travelling towards a surface."},{"id":"ncert7-science-11-2","grade":7,"subject":"Science","chapterNo":11,"chapter":"Light: Shadows and Reflections","level":"medium","q":"Which surface gives a clear reflection?","options":["A smooth plane mirror","Rough cloth","Unpolished wood","A sheet of paper"],"correct":0,"why":"A smooth mirror reflects light in an orderly way and forms a clear image."},{"id":"ncert7-science-12-1","grade":7,"subject":"Science","chapterNo":12,"chapter":"Earth, Moon, and the Sun","level":"easy","q":"Why do we see different phases of the Moon?","options":["We see different portions of its sunlit half as it orbits Earth","Earth's shadow covers it every night","The Moon changes its shape","Clouds cut pieces from the Moon"],"correct":0,"why":"The Moon's changing position relative to Earth and Sun changes the visible sunlit portion."},{"id":"ncert7-science-12-2","grade":7,"subject":"Science","chapterNo":12,"chapter":"Earth, Moon, and the Sun","level":"medium","q":"What causes day and night on Earth?","options":["Earth rotates on its axis","The Moon rotates around Earth","The Sun moves around Earth each day","Earth stops moving at night"],"correct":0,"why":"Earth's rotation causes different places to face towards or away from the Sun."}]);


/* Class 7 Ganita Prakash Parts I & II: 30 original questions, two per chapter. */
window.GB_NCERT_QUESTIONS.push(...[{"id":"ncert7-mathematics-1","grade":7,"subject":"Mathematics","chapterNo":1,"chapter":"Large Numbers Around Us","level":"easy","q":"A town has a population of 3,45,600. What is the place value of 4 in this number?","options":["4,000","40,000","400","4"],"correct":1,"why":"The digit 4 is in the ten-thousands place, so its place value is 40,000."},{"id":"ncert7-mathematics-2","grade":7,"subject":"Mathematics","chapterNo":1,"chapter":"Large Numbers Around Us","level":"medium","q":"Which is the greatest number?","options":["8,75,430","8,57,430","8,74,530","8,75,340"],"correct":0,"why":"Compare digits from left to right; 8,75,430 is the greatest."},{"id":"ncert7-mathematics-3","grade":7,"subject":"Mathematics","chapterNo":2,"chapter":"Arithmetic Expressions","level":"easy","q":"Evaluate 18 + 6 × 4 using the usual order of operations.","options":["96","42","72","48"],"correct":1,"why":"Multiplication comes before addition: 18 + 24 = 42."},{"id":"ncert7-mathematics-4","grade":7,"subject":"Mathematics","chapterNo":2,"chapter":"Arithmetic Expressions","level":"medium","q":"Which expression represents 'subtract 7 from the product of 9 and 5'?","options":["9 × (5 − 7)","9 × 5 − 7","9 + 5 − 7","9 × (5 + 7)"],"correct":1,"why":"First find the product 9 × 5, then subtract 7."},{"id":"ncert7-mathematics-5","grade":7,"subject":"Mathematics","chapterNo":3,"chapter":"A Peek Beyond the Point","level":"easy","q":"What is 3.75 + 2.6?","options":["5.81","6.35","6.25","5.35"],"correct":1,"why":"Write 2.6 as 2.60; 3.75 + 2.60 = 6.35."},{"id":"ncert7-mathematics-6","grade":7,"subject":"Mathematics","chapterNo":3,"chapter":"A Peek Beyond the Point","level":"medium","q":"Which is the smallest decimal number?","options":["4.08","4.8","4.18","4.008"],"correct":3,"why":"Compare equal-length decimal forms: 4.008 is smaller than 4.080, 4.800 and 4.180."},{"id":"ncert7-mathematics-7","grade":7,"subject":"Mathematics","chapterNo":4,"chapter":"Expressions using Letter-Numbers","level":"easy","q":"If x = 6, what is the value of 3x + 4?","options":["18","22","24","10"],"correct":1,"why":"Substitute x = 6: 3 × 6 + 4 = 22."},{"id":"ncert7-mathematics-8","grade":7,"subject":"Mathematics","chapterNo":4,"chapter":"Expressions using Letter-Numbers","level":"medium","q":"Which expression means '5 more than twice a number n'?","options":["5n + 2","2(n + 5)","2n + 5","n + 10"],"correct":2,"why":"Twice n is 2n; five more gives 2n + 5."},{"id":"ncert7-mathematics-9","grade":7,"subject":"Mathematics","chapterNo":5,"chapter":"Parallel and Intersecting Lines","level":"easy","q":"When a transversal cuts two parallel lines, corresponding angles are:","options":["Equal","Always supplementary","Always right angles","Unequal"],"correct":0,"why":"Corresponding angles are equal when the two lines are parallel."},{"id":"ncert7-mathematics-10","grade":7,"subject":"Mathematics","chapterNo":5,"chapter":"Parallel and Intersecting Lines","level":"medium","q":"Two angles forming a linear pair add up to:","options":["90°","180°","270°","360°"],"correct":1,"why":"A linear pair forms a straight angle of 180°."},{"id":"ncert7-mathematics-11","grade":7,"subject":"Mathematics","chapterNo":6,"chapter":"Number Play","level":"easy","q":"Which of these numbers is odd?","options":["246","518","731","902"],"correct":2,"why":"A number ending in 1 is odd."},{"id":"ncert7-mathematics-12","grade":7,"subject":"Mathematics","chapterNo":6,"chapter":"Number Play","level":"medium","q":"What is the next number in the sequence 1, 1, 2, 3, 5, 8, ...?","options":["11","12","13","15"],"correct":2,"why":"Each term is the sum of the previous two: 5 + 8 = 13."},{"id":"ncert7-mathematics-13","grade":7,"subject":"Mathematics","chapterNo":7,"chapter":"A Tale of Three Intersecting Lines","level":"easy","q":"Can lengths 3 cm, 4 cm and 8 cm form a triangle?","options":["Yes, always","No, because 3 + 4 is less than 8","No, because all sides differ","Yes, because 8 is the longest"],"correct":1,"why":"The sum of any two sides must be greater than the third; 3 + 4 is not greater than 8."},{"id":"ncert7-mathematics-14","grade":7,"subject":"Mathematics","chapterNo":7,"chapter":"A Tale of Three Intersecting Lines","level":"medium","q":"An equilateral triangle has each angle equal to:","options":["45°","60°","90°","120°"],"correct":1,"why":"The three equal angles sum to 180°, so each is 60°."},{"id":"ncert7-mathematics-15","grade":7,"subject":"Mathematics","chapterNo":8,"chapter":"Working with Fractions","level":"easy","q":"What is 2/3 × 3/5?","options":["2/5","5/8","6/8","1/5"],"correct":0,"why":"Multiply numerators and denominators: 6/15, which simplifies to 2/5."},{"id":"ncert7-mathematics-16","grade":7,"subject":"Mathematics","chapterNo":8,"chapter":"Working with Fractions","level":"medium","q":"What is 3/4 ÷ 1/2?","options":["3/8","2/3","3/2","1/4"],"correct":2,"why":"Divide by a fraction by multiplying by its reciprocal: 3/4 × 2 = 3/2."},{"id":"ncert7-mathematics-17","grade":7,"subject":"Mathematics","chapterNo":9,"chapter":"Geometric Twins","level":"easy","q":"Two triangles are congruent when:","options":["They have the same shape and the same size","They have only equal areas","They have one equal angle","They are both right-angled"],"correct":0,"why":"Congruent figures match exactly in shape and size."},{"id":"ncert7-mathematics-18","grade":7,"subject":"Mathematics","chapterNo":9,"chapter":"Geometric Twins","level":"medium","q":"If two sides and the included angle of one triangle equal the corresponding parts of another, which criterion applies?","options":["SSS","SAS","ASA","RHS"],"correct":1,"why":"The Side-Angle-Side criterion establishes congruence."},{"id":"ncert7-mathematics-19","grade":7,"subject":"Mathematics","chapterNo":10,"chapter":"Operations with Integers","level":"easy","q":"What is (−7) × (−4)?","options":["−28","28","−11","11"],"correct":1,"why":"The product of two negative integers is positive: 7 × 4 = 28."},{"id":"ncert7-mathematics-20","grade":7,"subject":"Mathematics","chapterNo":10,"chapter":"Operations with Integers","level":"medium","q":"What is −24 ÷ 6?","options":["4","−4","−18","18"],"correct":1,"why":"A negative divided by a positive is negative; 24 ÷ 6 = 4."},{"id":"ncert7-mathematics-21","grade":7,"subject":"Mathematics","chapterNo":11,"chapter":"Finding Common Ground","level":"easy","q":"What is the HCF of 18 and 24?","options":["3","6","9","12"],"correct":1,"why":"The greatest common factor shared by 18 and 24 is 6."},{"id":"ncert7-mathematics-22","grade":7,"subject":"Mathematics","chapterNo":11,"chapter":"Finding Common Ground","level":"medium","q":"What is the LCM of 6 and 8?","options":["12","18","24","48"],"correct":2,"why":"The smallest common multiple of 6 and 8 is 24."},{"id":"ncert7-mathematics-23","grade":7,"subject":"Mathematics","chapterNo":12,"chapter":"Another Peek Beyond the Point","level":"easy","q":"What is 7.2 − 3.85?","options":["3.35","4.35","3.45","4.25"],"correct":0,"why":"Write 7.2 as 7.20; 7.20 − 3.85 = 3.35."},{"id":"ncert7-mathematics-24","grade":7,"subject":"Mathematics","chapterNo":12,"chapter":"Another Peek Beyond the Point","level":"medium","q":"A ribbon is 2.5 m long. How many centimetres is this?","options":["25 cm","250 cm","2,500 cm","0.25 cm"],"correct":1,"why":"One metre is 100 centimetres, so 2.5 m = 250 cm."},{"id":"ncert7-mathematics-25","grade":7,"subject":"Mathematics","chapterNo":13,"chapter":"Connecting the Dots...","level":"easy","q":"On a coordinate grid, the point (3, 2) is located by moving:","options":["2 right, then 3 up","3 right, then 2 up","3 left, then 2 down","2 left, then 3 up"],"correct":1,"why":"The first coordinate gives the horizontal move; the second gives the vertical move."},{"id":"ncert7-mathematics-26","grade":7,"subject":"Mathematics","chapterNo":13,"chapter":"Connecting the Dots...","level":"medium","q":"Which ordered pair lies on the y-axis?","options":["(4, 0)","(0, 5)","(3, 2)","(−2, 1)"],"correct":1,"why":"Every point on the y-axis has x-coordinate 0."},{"id":"ncert7-mathematics-27","grade":7,"subject":"Mathematics","chapterNo":14,"chapter":"Constructions and Tilings","level":"easy","q":"Which instrument is used to draw a circle with a chosen radius?","options":["Compass","Protractor","Set square only","Divider only"],"correct":0,"why":"A compass draws circles and arcs with a chosen radius."},{"id":"ncert7-mathematics-28","grade":7,"subject":"Mathematics","chapterNo":14,"chapter":"Constructions and Tilings","level":"medium","q":"A shape tiles a surface without gaps or overlaps. This arrangement is called:","options":["Tessellation","Reflection","Translation only","Estimation"],"correct":0,"why":"A tessellation covers a surface with repeated shapes without gaps or overlaps."},{"id":"ncert7-mathematics-29","grade":7,"subject":"Mathematics","chapterNo":15,"chapter":"Finding the Unknown","level":"easy","q":"If x + 9 = 17, what is x?","options":["6","7","8","9"],"correct":2,"why":"Subtract 9 from both sides: x = 17 − 9 = 8."},{"id":"ncert7-mathematics-30","grade":7,"subject":"Mathematics","chapterNo":15,"chapter":"Finding the Unknown","level":"medium","q":"If 4y = 28, what is y?","options":["6","7","8","9"],"correct":1,"why":"Divide both sides by 4: y = 28 ÷ 4 = 7."}]);


