window.GB_NCERT_QUESTIONS.push(...[{"id":"ncert7-english-1","grade":7,"subject":"English","chapterNo":1,"chapter":"The Day the River Spoke","level":"easy","q":"In a story where a river is given a voice, what literary device is being used?","options":["Personification","Hyperbole","Alliteration","Onomatopoeia"],"correct":0,"why":"Personification gives human qualities or a voice to a non-human thing."},{"id":"ncert7-english-2","grade":7,"subject":"English","chapterNo":1,"chapter":"The Day the River Spoke","level":"medium","q":"Which response best shows responsible care for a river?","options":["Dumping waste because water flows away","Reducing pollution and keeping its banks clean","Removing all plants from its banks","Using more plastic near the water"],"correct":1,"why":"Protecting water bodies requires preventing pollution and caring for their surroundings."},{"id":"ncert7-english-3","grade":7,"subject":"English","chapterNo":2,"chapter":"Try Again","level":"easy","q":"What is the central message of the poem 'Try Again'?","options":["Give up after one failure","Keep making sincere efforts after setbacks","Success depends only on luck","Avoid difficult tasks"],"correct":1,"why":"The poem encourages perseverance and renewed effort after failure."},{"id":"ncert7-english-4","grade":7,"subject":"English","chapterNo":2,"chapter":"Try Again","level":"medium","q":"Which word is closest in meaning to 'persevere'?","options":["Persist","Forget","Hesitate","Retreat"],"correct":0,"why":"To persevere is to continue trying despite difficulty."},{"id":"ncert7-english-5","grade":7,"subject":"English","chapterNo":3,"chapter":"Three Days to See","level":"easy","q":"The account of imagining three days of sight mainly encourages readers to:","options":["Appreciate everyday experiences and senses","Avoid observing nature","Ignore people around them","Spend all day indoors"],"correct":0,"why":"The reflection invites readers to value ordinary sights and experiences."},{"id":"ncert7-english-6","grade":7,"subject":"English","chapterNo":3,"chapter":"Three Days to See","level":"medium","q":"Which habit can help a person notice more in daily life?","options":["Rushing without looking","Observing people and nature carefully","Avoiding questions","Using only one sense"],"correct":1,"why":"Careful observation helps us appreciate details often overlooked."},{"id":"ncert7-english-7","grade":7,"subject":"English","chapterNo":4,"chapter":"Animals, Birds, and Dr. Dolittle","level":"easy","q":"Dr. Dolittle is associated with which unusual ability?","options":["Understanding and communicating with animals","Flying without equipment","Predicting every storm","Building underwater cities"],"correct":0,"why":"The character is known for communicating with animals."},{"id":"ncert7-english-8","grade":7,"subject":"English","chapterNo":4,"chapter":"Animals, Birds, and Dr. Dolittle","level":"medium","q":"Which quality is most important when caring for animals?","options":["Kindness and respect for their needs","Treating them as toys","Ignoring signs of distress","Feeding them anything"],"correct":0,"why":"Responsible animal care requires empathy and attention to their needs."},{"id":"ncert7-english-9","grade":7,"subject":"English","chapterNo":5,"chapter":"A Funny Man","level":"easy","q":"What is the main purpose of humour in a poem?","options":["To create amusement or a playful effect","To provide laboratory instructions","To list historical dates only","To give legal rules"],"correct":0,"why":"Humour uses amusing situations or language to entertain the reader."},{"id":"ncert7-english-10","grade":7,"subject":"English","chapterNo":5,"chapter":"A Funny Man","level":"medium","q":"A poem describes an impossible event for comic effect. This is most likely an example of:","options":["Absurd or exaggerated humour","A scientific report","A formal notice","A factual biography"],"correct":0,"why":"Absurdity and exaggeration can create a comic effect."},{"id":"ncert7-english-11","grade":7,"subject":"English","chapterNo":6,"chapter":"Say the Right Thing","level":"easy","q":"Why is choosing words carefully important in conversation?","options":["Words can affect how others feel and understand us","Words never influence relationships","Only long words are polite","Speaking quickly always prevents mistakes"],"correct":0,"why":"Thoughtful language supports clear and respectful communication."},{"id":"ncert7-english-12","grade":7,"subject":"English","chapterNo":6,"chapter":"Say the Right Thing","level":"medium","q":"Which reply is the most polite when you disagree?","options":["That is a foolish idea","I see your point, but I think differently because…","Be quiet","You are always wrong"],"correct":1,"why":"Respectful disagreement explains a different view without insulting the other person."},{"id":"ncert7-english-13","grade":7,"subject":"English","chapterNo":7,"chapter":"My Brother’s Great Invention","level":"easy","q":"What usually makes an invention useful?","options":["It solves a problem or meets a need","It is complicated even when unnecessary","It is never tested","It cannot be improved"],"correct":0,"why":"Useful inventions address a real need or solve a problem."},{"id":"ncert7-english-14","grade":7,"subject":"English","chapterNo":7,"chapter":"My Brother’s Great Invention","level":"medium","q":"Which is the best first step when developing an invention?","options":["Identify a problem to solve","Build randomly without a purpose","Avoid testing ideas","Copy without understanding"],"correct":0,"why":"Design begins by understanding the problem and the people who experience it."},{"id":"ncert7-english-15","grade":7,"subject":"English","chapterNo":8,"chapter":"Paper Boats","level":"easy","q":"A paper boat floating on water can symbolise:","options":["Imagination, hope or childhood play","A permanent building","A machine for measuring heat","A legal document"],"correct":0,"why":"A small paper boat can carry imaginative meanings such as hope and play."},{"id":"ncert7-english-16","grade":7,"subject":"English","chapterNo":8,"chapter":"Paper Boats","level":"medium","q":"Which property helps a paper boat float briefly?","options":["Its shape displaces water and its overall density can be low enough","Paper always repels water","It has no mass","Water has no upward force"],"correct":0,"why":"A boat floats when buoyancy balances its weight; its shape helps displace water."},{"id":"ncert7-english-17","grade":7,"subject":"English","chapterNo":9,"chapter":"North, South, East, West","level":"easy","q":"Which direction is opposite to north?","options":["South","East","West","North-east"],"correct":0,"why":"South is directly opposite north on a compass."},{"id":"ncert7-english-18","grade":7,"subject":"English","chapterNo":9,"chapter":"North, South, East, West","level":"medium","q":"If you face east and turn left, which direction do you face?","options":["North","South","West","North-west"],"correct":0,"why":"Turning left from east points towards north."},{"id":"ncert7-english-19","grade":7,"subject":"English","chapterNo":10,"chapter":"The Tunnel","level":"easy","q":"In a suspenseful story, a tunnel often helps create a feeling of:","options":["Mystery and uncertainty","Complete certainty","A cheerful celebration only","A scientific measurement"],"correct":0,"why":"A dark or unfamiliar tunnel can create suspense and uncertainty in a narrative."},{"id":"ncert7-english-20","grade":7,"subject":"English","chapterNo":10,"chapter":"The Tunnel","level":"medium","q":"Which action is safest when exploring an unfamiliar tunnel?","options":["Enter alone without telling anyone","Follow safety rules and go with authorised guidance","Touch unknown electrical equipment","Ignore warning signs"],"correct":1,"why":"Unfamiliar tunnels can be dangerous; follow official safety guidance and never trespass."},{"id":"ncert7-english-21","grade":7,"subject":"English","chapterNo":11,"chapter":"Travel","level":"easy","q":"Which detail is most useful when planning a journey?","options":["Route, timing and essential arrangements","Only the colour of luggage","The number of advertisements seen","A random guess about distance"],"correct":0,"why":"Good travel planning considers route, time and practical requirements."},{"id":"ncert7-english-22","grade":7,"subject":"English","chapterNo":11,"chapter":"Travel","level":"medium","q":"A travel poem may use sensory details mainly to:","options":["Help readers imagine places and experiences","Replace every verb with a number","Prove a mathematical theorem","Give only ticket prices"],"correct":0,"why":"Sensory details help readers picture and experience a place through language."},{"id":"ncert7-english-23","grade":7,"subject":"English","chapterNo":12,"chapter":"Conquering the Summit","level":"easy","q":"Reaching a mountain summit often requires:","options":["Preparation, patience and teamwork","Ignoring weather conditions","Carrying no water","Rushing without a plan"],"correct":0,"why":"Mountaineering demands preparation, endurance, sound decisions and often teamwork."},{"id":"ncert7-english-24","grade":7,"subject":"English","chapterNo":12,"chapter":"Conquering the Summit","level":"medium","q":"Why should climbers check weather conditions before an ascent?","options":["Weather can change safety and route conditions","Weather has no effect on mountains","It guarantees an easy climb","It replaces the need for equipment"],"correct":0,"why":"Wind, storms, temperature and visibility can make climbing dangerous."},{"id":"ncert7-english-25","grade":7,"subject":"English","chapterNo":13,"chapter":"A Homage to Our Brave Soldiers","level":"easy","q":"The word 'homage' most nearly means:","options":["An expression of deep respect","A complaint","A casual greeting","A competition"],"correct":0,"why":"Homage is a public expression of respect or honour."},{"id":"ncert7-english-26","grade":7,"subject":"English","chapterNo":13,"chapter":"A Homage to Our Brave Soldiers","level":"medium","q":"Which action is a meaningful way to honour people who serve the country?","options":["Remembering their service and supporting their families","Spreading unverified rumours","Damaging public memorials","Ignoring their contributions"],"correct":0,"why":"Respectful remembrance and support for service members and families are constructive ways to honour them."},{"id":"ncert7-english-27","grade":7,"subject":"English","chapterNo":14,"chapter":"My Dear Soldiers","level":"easy","q":"A poem addressed directly to soldiers is using:","options":["Direct address","A recipe format","A weather report","A mathematical proof"],"correct":0,"why":"Addressing someone directly is a poetic technique that can create a personal tone."},{"id":"ncert7-english-28","grade":7,"subject":"English","chapterNo":14,"chapter":"My Dear Soldiers","level":"medium","q":"Which theme is most likely central to a tribute to soldiers?","options":["Courage, service and sacrifice","Shopping and advertising","Cooking instructions","Traffic regulations"],"correct":0,"why":"Tributes to soldiers commonly recognise courage, service and sacrifice."},{"id":"ncert7-english-29","grade":7,"subject":"English","chapterNo":15,"chapter":"Rani Abbakka","level":"easy","q":"Rani Abbakka is remembered in Indian history for resisting which colonial power?","options":["The Portuguese","The French","The Dutch","The British"],"correct":0,"why":"Rani Abbakka of Ullal is remembered for resisting Portuguese expansion on the coast."},{"id":"ncert7-english-30","grade":7,"subject":"English","chapterNo":15,"chapter":"Rani Abbakka","level":"medium","q":"Ullal, associated with Rani Abbakka, is located in present-day:","options":["Karnataka","Punjab","Assam","Rajasthan"],"correct":0,"why":"Ullal is a coastal town near Mangaluru in Karnataka."}]);


